def _same_mouth(g,src,owner,t):
    """Two curb-sector ends belonging to the same authoritative mouth row.

    Their crown contact is prescribed analytically, including the zero-width
    side of a half profile. Keep independent clearance tests against every
    other sample; nearby positions alone never establish this identity.
    """
    count=c._stat(g,src,c.named(g,'st_cg_owner','INT'),'Max')+1.
    def endpoint(side,q):
        first=g.math('LESS_THAN',q,1e-7);last=g.math('GREATER_THAN',q,1.-1e-7)
        return first+last,c.choose(g,last,g.math('MODULO',side+1.,count),side)
    fixed,a=endpoint(owner,t)
    other,b=endpoint(c.named(g,'st_cg_owner','INT'),c.named(g,'st_cg_t'))
    return fixed*other*g.math('COMPARE',a,b)


def _zero_depth_ray_cap(g,src,point,normal,owner,*,peer=None,reduce=True):
    """First forward hit of a normal ray on sampled static curb intervals.

    A zero-depth sector is a boundary curve, not a disk around every sample.
    Testing its segments retains physical barriers even between samples. This
    is a polyline clearance bound; final curved charts and mesh checks remain.
    """
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]) if peer is None else peer
    count=c._count(g,src)
    nxt=g.math('MINIMUM',i+1.,count-1.)
    a=c._vec(g,g.position() if peer is None else c._sample(g,src,g.position(),peer,'FLOAT_VECTOR'))
    b=c._vec(g,c._sample(g,src,g.position(),nxt,'FLOAT_VECTOR'))
    delta=c._sub(a,point);edge=c._sub(b,a);det=c._cross(normal,edge)
    # Bound float32 cancellation in each 2D orientation predicate. A fixed
    # absolute epsilon misclassifies rotated collinear barriers as misses.
    def cross_error(a,b):
        return (4.*2.**-23)*(g.math('ABSOLUTE',a[0]*b[1])+g.math('ABSOLUTE',a[1]*b[0]))+1e-12
    nonparallel=g.math('GREATER_THAN',g.math('ABSOLUTE',det),cross_error(normal,edge))
    safe=c.choose(g,nonparallel,det,1.)
    distance=c._cross(delta,edge)/safe;fraction=c._cross(delta,normal)/safe
    hit=nonparallel*g.math('GREATER_THAN',distance,-1e-7)
    hit=hit*g.math('GREATER_THAN',fraction,-1e-7)*g.math('LESS_THAN',fraction,1.+1e-7)
    ta=c._dot(delta,normal);tb=c._dot(c._sub(b,point),normal)
    collinear=(1.-nonparallel)*g.math('LESS_THAN',g.math('ABSOLUTE',c._cross(delta,normal)),cross_error(delta,normal))
    collinear=collinear*g.math('GREATER_THAN',g.math('MAXIMUM',ta,tb),-1e-7)
    cap=c.choose(g,hit,g.math('MAXIMUM',0.,distance),1e8)
    cap=g.math('MINIMUM',cap,c.choose(g,collinear,g.math('MAXIMUM',0.,g.math('MINIMUM',ta,tb)),1e8))
    read=lambda key,kind='FLOAT':c.named(g,'st_cg_'+key,kind) if peer is None else c._read(g,src,'st_cg_'+key,peer,kind)
    other=read('owner','INT');zero=g.math('LESS_THAN',read('nominal'),1e-7)
    eligible=zero*g.math('LESS_THAN',c._read(g,src,'st_cg_nominal',nxt),1e-7)
    eligible=eligible*g.math('COMPARE',other,c._read(g,src,'st_cg_owner',nxt,'INT'))
    eligible=eligible*(1.-g.math('COMPARE',owner,other))*g.math('LESS_THAN',i,count-1.5)
    value=c.choose(g,eligible,cap,1e8)
    return c._stat(g,src,value) if reduce else value


def _directional_cap(g,src,point,normal,own,owner,other,shared_mouth=None,*,zero_depth_rays=False,peer=None,reduce=True):
    """Allocate finite normal segments, rather than disks around curb samples.

    For two forward rays meeting at distances a,b, simultaneous growth with
    nominal lengths wi,wj first touches at max(a/wi,b/wj). The same symmetric
    limit is applied to both samples. Parallel opposing rays divide their
    separation; a parallel same-direction ray stops before the next origin.
    Zero-depth physical boundaries retain the conservative distance barrier.
    This is a sampled construction, not a continuous clearance certificate.
    """
    position=g.position() if peer is None else c._sample(g,src,g.position(),peer,'FLOAT_VECTOR')
    read=lambda key,kind='FLOAT':c.named(g,'st_cg_'+key,kind) if peer is None else c._read(g,src,'st_cg_'+key,peer,kind)
    delta=c._sub(c._vec(g,position),point)
    other_normal=c._vec(g,read('normal','FLOAT_VECTOR'))
    determinant=c._cross(normal,other_normal)
    nonparallel=g.math('GREATER_THAN',g.math('ABSOLUTE',determinant),1e-7)
    safe=c.choose(g,nonparallel,determinant,1.)
    a=c._cross(delta,other_normal)/safe;b=c._cross(delta,normal)/safe
    forward=g.math('GREATER_THAN',a,1e-7)*g.math('GREATER_THAN',b,1e-7)
    factor=g.math('MAXIMUM',a/g.math('MAXIMUM',own,1e-8),b/g.math('MAXIMUM',other,1e-8))
    cap=c.choose(g,nonparallel*forward,own*factor,1e8)
    along=c._dot(delta,normal)
    collinear=(1.-nonparallel)*g.math('LESS_THAN',g.math('ABSOLUTE',c._cross(delta,normal)),1e-5)
    opposed=g.math('LESS_THAN',c._dot(normal,other_normal),0.)
    parallel_limit=c.choose(g,opposed,along*own/g.math('MAXIMUM',own+other,1e-8),along)
    cap=g.math('MINIMUM',cap,c.choose(g,collinear*g.math('GREATER_THAN',along,0.),parallel_limit,1e8))
    cap=c.choose(g,g.math('LESS_THAN',other,1e-7),1e8 if zero_depth_rays else c._length(g,delta),cap)
    if shared_mouth is not None:cap=c.choose(g,shared_mouth,own,cap)
    eligible=1.-g.math('COMPARE',owner,read('owner','INT'))
    value=c.choose(g,eligible,cap,1e8)
    result=c._stat(g,src,value) if reduce else value
    if zero_depth_rays:result=g.math('MINIMUM',result,_zero_depth_ray_cap(g,src,point,normal,owner,peer=peer,reduce=reduce))
    return result


def _depth_query(g, src, at, own, cap, margin, *, directional=False):
    """Unchanged depth/compatibility arithmetic shared by query evaluators."""
    read=lambda key:c._read(g,src,'st_cg_'+key,at)
    ease=lambda q:q*q*(3.-2.*q)
    qa=c.bounded(g,read('distance')/g.math('MAXIMUM',read('start_width'),1e-8))
    qb=c.bounded(g,(read('length')-read('distance'))/g.math('MAXIMUM',read('end_width'),1e-8))
    taper=ease(qa)*ease(qb);factor=1.-margin*taper
    nominal=own*factor;limited=cap*factor;soft=margin*own*taper
    depth=.5*(nominal+limited-g.math('SQRT',(nominal-limited)**2.+soft**2.))
    if directional:
        # Rationalize the smooth minimum. Nearly parallel/unlimited rays can
        # have enormous caps; subtracting similar large values loses the band.
        difference=g.math('ABSOLUTE',nominal-limited)
        denominator=g.math('MAXIMUM',g.math('SQRT',difference**2.+soft**2.)+difference,1e-8)
        depth=g.math('MINIMUM',nominal,limited)-.5*soft**2./denominator
    # Clamp endpoint arithmetic to the specified full profile. A separate
    # compatibility check rejects contradictory sampled clearance constraints.
    endpoint=g.math('LESS_THAN',read('t'),1e-7)+g.math('GREATER_THAN',read('t'),1.-1e-7)
    collapsed=g.math('LESS_THAN',own,1e-7)
    depth=c.choose(g,collapsed,0.,c.choose(g,endpoint,own,depth))
    compatible=c.choose(g,collapsed,1.,g.math('GREATER_THAN',cap,own-1e-5))
    good=c.choose(g,endpoint,compatible,1.)*c.choose(g,collapsed,1.,g.math('GREATER_THAN',depth,1e-7))
    return depth,good


def allocate(*,preserve_breaks=False,directional=False,intervals=False,exact_mouths=False,all_intervals=False,mapped=False,curvature_limits=False,zero_depth_rays=False):
    name='Prochitecture Streets / Sampled weighted profile clearance'+(' with knots v2' if preserve_breaks else ' v1')
    if directional:name='Prochitecture Streets / Sampled normal profile clearance'+(' with knots' if preserve_breaks else '')+' v1'
    if intervals:name+=' / Taper intervals v1'
    if exact_mouths:name+=' / Exact mouth contacts v1'
    if all_intervals:
        assert intervals
        name+=' / All moving intervals v2'
    if mapped:name+=' / Attribute map v1'
    if curvature_limits:name+=' / Curvature limit v1'
    if zero_depth_rays:name+=' / Directed static curb v2'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name);g.socket('Geometry','NodeSocketGeometry');g.socket('Input Valid','NodeSocketBool')
    g.socket('Margin','NodeSocketFloat',default=.025)
    g.socket('Geometry','NodeSocketGeometry','OUTPUT');g.socket('Valid','NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');src=inp.outputs['Geometry'];count=c._count(g,src);margin=c.V(g,inp.outputs['Margin'])
    valid=c.V(g,inp.outputs['Input Valid'])*g.math('GREATER_THAN',count,.5)*g.math('LESS_THAN',count,MAX_SAMPLES+.5)
    valid=valid*g.math('GREATER_THAN',margin,0.)*g.math('LESS_THAN',margin,.25)
    fields=(('owner','INT'),('t','FLOAT'),('nominal','FLOAT'),('distance','FLOAT'),('length','FLOAT'),
            ('start_width','FLOAT'),('end_width','FLOAT'),('normal','FLOAT_VECTOR'))
    if curvature_limits:fields+= (('curvature_cap','FLOAT'),)
    if mapped:
        ri=g.node('GeometryNodeForeachGeometryElementInput','Independent full-clearance queries')
        ro=g.node('GeometryNodeForeachGeometryElementOutput');ro.domain='POINT'
        ro.generation_items.clear()
        for kind,key in (('FLOAT','Cap'),('FLOAT','Depth'),('BOOLEAN','Valid')):ro.main_items.new(kind,key)
        ri.pair_with_output(ro)
        index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
        seed=g.setpos(c._line(g,count),g.xyz(*c._vec(g,c._sample(g,src,g.position(),index,'FLOAT_VECTOR'))))
        for key,kind in fields:seed=c._store(g,seed,'st_cg_'+key,c._read(g,src,'st_cg_'+key,index,kind),kind)
        if preserve_breaks:seed=c._store(g,seed,'st_cg_break',c._read(g,src,'st_cg_break',index,'BOOLEAN'),'BOOLEAN')
        g.bind(boundary._empty(g,seed,valid),ri.inputs['Geometry']);at=c.V(g,ri.outputs['Index'])
    else:
        ri=g.node('GeometryNodeRepeatInput','Allocate each sample from all other curb sectors');ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
        g.bind(c.choose(g,valid,count,0,'INT'),ri.inputs['Iterations']);at=c.V(g,ri.outputs['Iteration'])
    read=lambda key,kind='FLOAT':c._read(g,src,'st_cg_'+key,at,kind)
    own=read('nominal');owner=read('owner','INT');other=c.named(g,'st_cg_nominal')
    point=c._vec(g,c._sample(g,src,g.position(),at,'FLOAT_VECTOR'))
    distance=c._length(g,c._sub(c._vec(g,g.position()),point))
    # Zero-depth median boundaries remain physical barriers. They receive no
    # width themselves but limit an adjacent band to the full separation.
    eligible=1.-g.math('COMPARE',owner,c.named(g,'st_cg_owner','INT'))
    candidate=distance*own/g.math('MAXIMUM',own+other,1e-8)
    shared=_same_mouth(g,src,owner,read('t')) if exact_mouths else None
    if shared is not None:candidate=c.choose(g,shared,own,candidate)
    cap=(_directional_cap(g,src,point,c._vec(g,read('normal','FLOAT_VECTOR')),own,owner,other,shared,zero_depth_rays=zero_depth_rays)
         if directional else c._stat(g,src,c.choose(g,eligible,candidate,1e8)))
    if intervals:
        assert directional
        from . import curved_normal_interval_nodes
        zero_start=g.math('LESS_THAN',c.named(g,'st_cg_start_width'),1e-7)
        zero_end=g.math('LESS_THAN',c.named(g,'st_cg_end_width'),1e-7)
        mixed=c._stat(g,src,g.math('ABSOLUTE',zero_start-zero_end),'Max')
        interval_cap=g.math('MINIMUM',cap,curved_normal_interval_nodes.cap(g,src,at,count,exact_mouths=all_intervals and exact_mouths))
        # Compound sides can require directional clearance without a tapered
        # half profile. Their moving fronts still need interval contact tests;
        # testing isolated normal rays can miss crossings between the rays.
        cap=interval_cap if all_intervals else c.choose(g,mixed,interval_cap,cap)
    if curvature_limits:
        # An inward normal band must stop before the focal distance 1/kappa.
        # The existing interior margin keeps its guide strictly before it;
        # prescribed full mouth widths still undergo compatibility checks.
        cap=g.math('MINIMUM',cap,read('curvature_cap'))
    depth,good=_depth_query(g,src,at,own,cap,margin,directional=directional)
    if mapped:
        # The queries are independent. Return attributes on the original rows
        # instead of allocating and joining a point mesh on every iteration.
        # Do not request the zone's Element output: no sub-geometries are needed.
        for key,value in (('Cap',cap),('Depth',depth),('Valid',good)):g.bind(value,ro.inputs[key])
        result=ro.outputs['Geometry']
        for key,kind in (('Cap','FLOAT'),('Depth','FLOAT'),('Valid','BOOLEAN')):
            result=c._store(g,result,'st_cg_'+key.lower(),ro.outputs[key],kind)
        remove=g.node('GeometryNodeDeleteGeometry','Keep the original loose point-table contract')
        remove.domain='EDGE';remove.mode='EDGE_FACE';g.bind(result,remove.inputs['Geometry'])
        result=remove.outputs['Geometry']
    else:
        record=g.setpos(c._line(g,1),g.xyz(*point))
        for key,kind in fields:
            record=c._store(g,record,'st_cg_'+key,read(key,kind),kind)
        if preserve_breaks:record=c._store(g,record,'st_cg_break',read('break','BOOLEAN'),'BOOLEAN')
        for key,value,kind in (('cap',cap,'FLOAT'),('depth',depth,'FLOAT'),('valid',good,'BOOLEAN')):
            record=c._store(g,record,'st_cg_'+key,value,kind)
        g.bind(boundary._join(g,ri.outputs['Geometry'],record),ro.inputs['Geometry'])
        result=ro.outputs['Geometry']
    valid=valid*c._stat(g,result,c.named(g,'st_cg_valid','BOOLEAN'))
    out=g.node('NodeGroupOutput');g.bind(result,out.inputs['Geometry']);g.bind(valid,out.inputs['Valid'])
    return g.g


def adaptive(*,preserve_breaks=False,tapered=False,exact_mouths=False,all_intervals=False,mapped=False,curvature_limits=False,zero_depth_rays=False):
    """Keep feasible conservative bands; extend incompatible endpoint layouts.

    The directional branch is selected by the computed constraints, never by a
    fixture identity. It is not an unconditional replacement: finite sampling
    alone can miss interpolated band overlap. All downstream cell, projection,
    profile and chart-overlap checks remain mandatory for either branch.
    """
    name='Prochitecture Streets / Adaptive sampled profile clearance'+(' with knots' if preserve_breaks else '')+' v1'
    if tapered:name+=' / Taper intervals v1'
    if exact_mouths:name+=' / Exact mouth contacts v1'
    if all_intervals:name+=' / All moving intervals v2'
    if mapped:name+=' / Attribute map v1'
    if curvature_limits:name+=' / Curvature limit v1'
    if zero_depth_rays:name+=' / Directed static curb v2'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name);g.socket('Geometry','NodeSocketGeometry');g.socket('Input Valid','NodeSocketBool')
    g.socket('Margin','NodeSocketFloat',default=.025)
    g.socket('Geometry','NodeSocketGeometry','OUTPUT');g.socket('Valid','NodeSocketBool','OUTPUT')
    g.socket('Directional','NodeSocketBool','OUTPUT');inp=g.node('NodeGroupInput')
    nodes=[]
    for directional in (False,True):
        options=dict(preserve_breaks=preserve_breaks,directional=directional,
            intervals=(tapered or all_intervals) and directional,exact_mouths=exact_mouths,
            all_intervals=all_intervals and directional,curvature_limits=curvature_limits,
            zero_depth_rays=zero_depth_rays and directional)
        n=g.node('GeometryNodeGroup')
        if mapped and directional:
            from . import curved_clearance_batch_nodes
            n.node_tree=curved_clearance_batch_nodes.build(**options)
        else:
            n.node_tree=allocate(**options,mapped=mapped)
        for key in ('Geometry','Input Valid','Margin'):g.bind(inp.outputs[key],n.inputs[key])
        nodes.append(n)
    preferred,extension=nodes;use_preferred=preferred.outputs['Valid']
    geo=c.choose(g,use_preferred,preferred.outputs['Geometry'],extension.outputs['Geometry'],'GEOMETRY')
    valid=c.choose(g,use_preferred,True,extension.outputs['Valid'],'BOOLEAN')
    directional=(1.-c.V(g,use_preferred))*c.V(g,inp.outputs['Input Valid'])
    geo=c._store(g,geo,'st_cg_directional',directional,'BOOLEAN')
    out=g.node('NodeGroupOutput')
    for key,value in (('Geometry',geo),('Valid',valid),('Directional',directional)):g.bind(value,out.inputs[key])
    return g.g
